import sqlite3
from contextlib import contextmanager
from typing import Iterator, Optional, Tuple

DEFAULT_DB_PATH = "users.db"

# A user row is (id, email).
UserRecord = Tuple[int, str]


def get_connection(path: str = DEFAULT_DB_PATH) -> sqlite3.Connection:
    """Open a connection to the SQLite database at ``path``."""
    conn = sqlite3.connect(path)
    # Pragmas that speed up read-heavy access without sacrificing safety.
    conn.execute("PRAGMA journal_mode = WAL")
    conn.execute("PRAGMA synchronous = NORMAL")
    conn.execute("PRAGMA temp_store = MEMORY")
    return conn


@contextmanager
def connection_scope(path: str = DEFAULT_DB_PATH) -> Iterator[sqlite3.Connection]:
    """Yield a connection that is always closed when the block exits."""
    conn = get_connection(path)
    try:
        yield conn
    finally:
        conn.close()


def _find_user_by(
    conn: sqlite3.Connection, column: str, value: str
) -> Optional[UserRecord]:
    """Return the ``(id, email)`` for a row matching ``column = value``."""
    cursor = conn.execute(
        f"SELECT id, email FROM users WHERE {column} = ? LIMIT 1",
        (value,),
    )
    return cursor.fetchone()


def find_user(conn: sqlite3.Connection, username: str) -> Optional[UserRecord]:
    """Return the ``(id, email)`` for ``username``, or ``None`` if not found."""
    return _find_user_by(conn, "name", username)


def find_user_by_email(conn: sqlite3.Connection, email: str) -> Optional[UserRecord]:
    """Return the ``(id, email)`` for ``email``, or ``None`` if not found."""
    return _find_user_by(conn, "email", email)


def handle_request(username: str) -> Optional[UserRecord]:
    """Look up ``username``, ensuring the connection is always closed."""
    with connection_scope() as conn:
        return find_user(conn, username)


